"use strict";(self.webpackChunksketch_blog=self.webpackChunksketch_blog||[]).push([[3320],{356(a,e,p){p.r(e),p.d(e,{_pageData:()=>n,default:()=>s});var h=p(641);const n=JSON.parse('{"path":"/notes/%E4%B9%A6%E5%BD%B1%E9%9F%B3%E6%B8%B8/%E8%A7%86%E9%A2%91/%E5%A5%87%E5%B7%A7%E5%87%BA%E7%A7%9F%E8%BD%A6.html","title":"奇巧出租车","lang":"zh-CN","frontmatter":{"title":"奇巧出租车","date":"2023-03-21T00:00:00.000Z","tags":["影视"]},"git":{},"filePathRelative":"notes/书影音游/视频/奇巧出租车.md"}'),t={name:"奇巧出租车.md"},s=(0,p(6262).A)(t,[["render",function(a,e,p,n,t,s){return(0,h.uX)(),(0,h.CE)("div",null,[...e[0]||(e[0]=[(0,h.Fv)('<h1 id="奇巧出租车" tabindex="-1"><a class="header-anchor" href="#奇巧出租车"><span>奇巧出租车</span></a></h1><p>动漫用一系列巧合构建了一个故事链。</p><p>讲述了很多人的历程与情感变化。</p><p>其中我印象最深的是田中和两个说脱口秀的故事线</p><h2 id="田中" tabindex="-1"><a class="header-anchor" href="#田中"><span>田中</span></a></h2><h3 id="故事线" tabindex="-1"><a class="header-anchor" href="#故事线"><span>故事线</span></a></h3><p>田中幼时因攀比之心不惜花费家中巨款，也要高价买绝款橡皮。</p><p>工作后又因想要游戏中的绝版渡渡鸟一直充钱。</p><p>但是事与愿违，幼时买的橡皮没有发货，橡皮热也很快散去。</p><p>渡渡鸟刚抽到手机就意外被车蹭入水中，数据丢失。</p><p>数据丢失之后，田中就彻底失去了生活的希望。只想杀掉开车的人。</p><p>报复成功后惊慌而逃，最后望水而悟，重新回去做了打工仔。</p><h3 id="病态的欲望" tabindex="-1"><a class="header-anchor" href="#病态的欲望"><span>病态的欲望？</span></a></h3><p>田中的故事，无论是买橡皮、抽渡渡鸟、还是去报复开车人，都充斥着病态的欲望和思想。</p>',14)])])}]])}}]);